import assert from 'node:assert/strict';
import path from 'node:path';

export async function inboxFindingJourney({api,group,out}){
 const state=()=>api.evaluate(async()=>{const r=await chrome.runtime.sendMessage({type:'workspace.state'});if(r.error)throw Error(r.error);return r.state;});
 const send=action=>api.evaluate(async action=>{const r=await chrome.runtime.sendMessage({type:'workspace.action',action});if(r.error)throw Error(r.error);return r;},action);
 const inbox=async({keyboard=false}={})=>{if(!await api.locator('#inbox').isVisible())await api.locator('#libraryToggle').click();await api.locator('#inbox').focus();if(keyboard)await api.locator('#inbox').press('Enter');else await api.locator('#inbox').click();await api.waitForFunction(()=>document.body.dataset.section==='research'&&document.querySelector('#scanName').textContent==='Inbox');assert.equal(await api.locator('#inbox').getAttribute('aria-current'),'page');assert.equal((await state()).activeScanId,null);assert.equal(await api.locator('#projects .selected').count(),0);await api.locator('#addSubject').waitFor({state:'hidden'});};
 for(const name of ['Research','Captures','Case','Settings']){await api.getByRole('tab',{name,exact:true}).click();await inbox({keyboard:name==='Settings'});await api.getByText('No findings yet',{exact:true}).waitFor();}
 await api.reload();await api.locator('.layout:not([inert])').waitFor();await inbox();
 group('Empty Inbox with zero cases always opens Research from every main view, highlights Inbox and supports keyboard activation and reload.');
 const items=[];for(const title of ['First fictional','Middle fictional','Last fictional'])items.push((await send({type:'item.save',kind:'note',scanId:null,title,body:'Fictional deletion fixture'})).result.id);
 await send({type:'task.create',scanId:null,title:'Keep this task'});
 const image=await api.evaluate(async()=>{const store=await import('./capture-store.js'),canvas=document.createElement('canvas');canvas.width=20;canvas.height=20;canvas.getContext('2d').fillRect(0,0,20,20);const blob=await new Promise(r=>canvas.toBlob(r)),c=await store.beginCapture({context:{},source:{url:'https://example.test/image.png',title:'Retained image'},mode:'source-image'});return store.completeCapture(c.id,{assets:[{blob,role:'original'}],dimensions:{width:20,height:20},scale:1});});
 await api.getByRole('tab',{name:'Captures',exact:true}).click();await inbox();await api.waitForFunction(()=>document.querySelectorAll('#items .card').length===3);assert.equal(await api.locator('#inboxCount').textContent(),'3');
 const card=id=>api.locator('[data-item-id="'+id+'"]');
 const remove=async(id,{cancel=false,keyboard=false}={})=>{const b=card(id).getByRole('button',{name:'Delete saved finding',exact:true});await b.focus();if(keyboard)await b.press('Enter');else await b.click();const d=api.getByRole('dialog',{name:'Delete this saved finding?',exact:true});await d.waitFor();assert.equal(await d.getByRole('button',{name:'Cancel',exact:true}).evaluate(e=>e===document.activeElement),true);await d.getByRole('button',{name:cancel?'Cancel':'Delete',exact:true}).click();await d.waitFor({state:'detached'});if(!cancel)await card(id).waitFor({state:'detached'});};
 await remove(items[1],{cancel:true});assert.equal((await state()).items.length,3);
 await api.locator('#localSearch').fill('Middle');await remove(items[1],{keyboard:true});assert.equal(await api.locator('#localSearch').inputValue(),'Middle');await api.getByText('No matching findings',{exact:true}).waitFor();assert.equal(await api.locator('#inboxCount').textContent(),'2');
 await api.locator('#localSearch').fill('');await remove(items[2]);await remove(items[0]);await api.getByText('No findings yet',{exact:true}).waitFor();assert.ok(await api.locator('#inboxCount').isHidden());assert.equal((await state()).tasks.length,1);
 assert.equal(await api.evaluate(async id=>(await(await import('./capture-store.js')).getAsset(id,{verify:true})).sha256,image.assetIds[0]),image.assets[0].sha256);
 await api.reload();await api.locator('.layout:not([inert])').waitFor();assert.equal((await state()).items.length,0);await api.getByText('No findings yet',{exact:true}).waitFor();
 group('Finding Delete supports cancel, keyboard, first/middle/last/only rows, stable filtering/counts and reload; Inbox image bytes and tasks are unchanged.');
 const create=async name=>{await api.getByRole('button',{name:'New case',exact:true}).click();await api.getByLabel('Case name',{exact:true}).fill(name);await api.getByRole('button',{name:'Create case',exact:true}).click();await api.getByRole('heading',{name,exact:true}).waitFor();const s=await state();return s.scans.find(x=>x.id===s.activeScanId);};
 const a=await create('CASE-46102');await api.getByRole('tab',{name:'Captures',exact:true}).click();await inbox();const b=await create('CASE-57213');await api.getByRole('tab',{name:'Case',exact:true}).click();await inbox();
 await api.setViewportSize({width:400,height:850});await api.getByRole('tab',{name:'Settings',exact:true}).click();await inbox({keyboard:true});assert.ok(await api.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await api.setViewportSize({width:1280,height:900});
 await api.locator('#projects').getByRole('button',{name:'CASE-46102',exact:true}).click();
 const finding=(await send({type:'item.save',kind:'account',scanId:a.id,entry:{url:'https://www.instagram.com/alex.example/',platform:'instagram',id:'9007199254740993123',status:'resolved',verifiedAt:1780000000000,verificationSource:'live'}})).result.id;
 const linked=await api.evaluate(async({finding,a})=>{const store=await import('./capture-store.js'),state=(await chrome.runtime.sendMessage({type:'workspace.state'})).state,subject=(await store.listSubjects(a.projectId))[0];await store.associateSubject(subject.id,[finding],state);const c=await store.beginCapture({context:await store.resolveCaptureDestination(state,a.id,subject.id),source:{url:'https://example.test/retained',title:'Linked screenshot'},mode:'visible',refs:{accountId:finding}});const canvas=document.createElement('canvas');canvas.width=10;canvas.height=10;const saved=await store.completeCapture(c.id,{assets:[{blob:await new Promise(r=>canvas.toBlob(r))}],dimensions:{width:10,height:10}});await chrome.runtime.sendMessage({type:'workspace.action',action:{type:'research.associate',subjectId:subject.id,itemId:finding,status:'confirmed',reason:'Explicit fictional link'}});return {subject,capture:saved};},{finding,a});
 await send({type:'item.save',kind:'note',scanId:b.id,title:'Unrelated case finding',body:'Keep'});await send({type:'task.create',scanId:a.id,title:'Keep case task'});
 await api.getByRole('tab',{name:'Research',exact:true}).click();await card(finding).waitFor();await api.screenshot({path:path.join(out,'finding-delete.png')});
 // Stale confirmation must reject a concurrent edit, with no partial deletion.
 await card(finding).getByRole('button',{name:'Delete saved finding',exact:true}).click();await send({type:'item.annotate',id:finding,annotation:'Changed elsewhere'});const stale=api.getByRole('dialog',{name:'Delete this saved finding?',exact:true});await stale.getByRole('button',{name:'Delete',exact:true}).click();await stale.getByRole('alert').getByText(/finding changed/).waitFor();await stale.getByRole('button',{name:'Cancel',exact:true}).click();
 await remove(finding);const after=await state();assert.ok(after.items.some(i=>i.title==='Unrelated case finding'));assert.equal(after.tasks.length,2);assert.equal(after.research.associations.length,0);
 const links=await api.evaluate(async({linked,finding,a})=>{const store=await import('./capture-store.js'),c=await store.getCapture(linked.capture.id),subjects=await store.listSubjects(a.projectId);let rejected=false;try{await store.associateSubject(linked.subject.id,[finding],{items:[{id:finding,kind:'account',projectId:a.projectId}]});}catch{rejected=true;}return {capture:c,subject:subjects.find(s=>s.id===linked.subject.id),rejected,sha:(await store.getAsset(c.assetIds[0],{verify:true})).sha256};},{linked,finding,a});assert.equal(links.capture.refs.accountId,null);assert.deepEqual(links.subject.accountObservationIds,[]);assert.ok(links.rejected);assert.equal(links.sha,linked.capture.assets[0].sha256);
 await api.evaluate(async()=>{const {createFullBackup,readFullBackup}=await import('./capture-backup.js');await readFullBackup(await createFullBackup((await chrome.runtime.sendMessage({type:'workspace.backup'})).backup));});
 group('Case/SOC finding deletion rejects stale confirmation, cleans explicit links/undo, preserves unrelated cases/tasks/images and leaves a valid binary backup.');
 for(const name of ['CASE-46102','CASE-57213']){await api.locator('#projects').getByRole('button',{name,exact:true}).click();await api.getByRole('tab',{name:'Settings',exact:true}).click();await api.getByRole('button',{name:'Delete case…',exact:true}).click();const d=api.getByRole('dialog',{name:'Delete case',exact:true});await d.getByLabel('Type the case name to confirm deletion: '+name,{exact:true}).fill(name);await d.getByRole('button',{name:'Delete without backup',exact:true}).click();await d.waitFor({state:'detached'});await inbox();}
 assert.equal((await state()).projects.length,0);await api.reload();await api.locator('.layout:not([inert])').waitFor();await inbox();
 await api.evaluate(async id=>{const store=await import('./capture-store.js');await store.deleteCaptures(store.captureDeleteGuard([await store.getCapture(id)]));},image.id);
 group('Inbox remains navigable with one/multiple cases, 400px Library, and after deletion of the last case.');
}
